contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint64 ts) public payable {
        require(msg.value >= 10 ether);

        uint snapshot = c.pastBlockTime();

        bool reverted;
        if (block.timestamp > snapshot) {
            try c.fallback{value: 10 ether}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
        } else {
            try c.fallback{value: 10 ether}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        }
    }

    receive() external payable {}
}

