contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint advance) public payable {
        require(amount >= 10 ether);
        require(address(this).balance >= amount);

        // First successful call: set pastBlockTime to a known baseline.
        uint t0 = block.timestamp;
        c.fallback{value: 10 ether}();
        uint p0 = c.pastBlockTime();

        // Now probe strictly-greater semantics; the probe value is always > p0.
        c.fallback{value: amount}();
        uint p1 = c.pastBlockTime();

        assert(p1 == block.timestamp + 1 && p0 == t0 + 1);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint advance) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount + 10 ether);

        // First successful call to establish a known pastBlockTime.
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "setup call failed");
        uint p0 = c.pastBlockTime();

        // We cannot directly set block.timestamp; probe with a call.
        // The deciding call uses exactly 10 ether from the parameter.
        (bool ok2, ) = address(c).call{value: amount}("");
        uint p1 = c.pastBlockTime();

        // The rule: the call succeeds iff current timestamp > p0.
        // After a successful call, p1 == block.timestamp + 1.
        // After a reverted call, p1 is unchanged.
        if (ok2) {
            assert(p1 == block.timestamp + 1);
        } else {
            assert(p1 == p0);
            assert(block.timestamp <= p0);
        }
    }

    receive() external payable {}
}

