contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint pastBefore = c.pastBlockTime();
        uint cBalanceBefore = address(c).balance;
        uint senderBalanceBefore = address(this).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint cBalanceAfter = address(c).balance;
        uint senderBalanceAfter = address(this).balance;

        bool success = !reverted;
        bool amountIsTenEther = (amount == 10 ether);
        bool timestampAdvanced = pastAfter == pastBefore + 1;

        // If the call reverted, the amount must not have been 10 ether, or the
        // timestamp precondition was not met. If it succeeded, it must have been a
        // 10 ether call, pastBlockTime must have advanced to exactly the previous
        // value plus one, and any balance of c at entry must have been sent to the caller.
        bool revertedOk = reverted
            ? (!amountIsTenEther || pastAfter != pastBefore + 1)
            : true;
        bool successOk = success
            ? (amountIsTenEther && timestampAdvanced)
            : true;
