contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // Precondition on the amount parameter only. The test always sends 10 ether
        // to the fallback; other amounts are allowed but then the call must revert.
        require(amount == 9 ether || amount == 10 ether || amount == 11 ether);
        require(address(this).balance >= amount);

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTimestamp = c.pastBlockTime();

        // General rule about the fallback entry:
        // - a call sending exactly 10 ether succeeds exactly when its timestamp is
        //   strictly greater than the previously recorded pastBlockTime and the block
        //   number is not a multiple of 15;
        // - a successful call whose block number is not a multiple of 15 sets
        //   pastBlockTime to that timestamp + 1, so it is strictly greater than the
        //   timestamp of the call and therefore strictly greater than the timestamp of
        //   the initial (zero) state.
        // The only observable post-state facts are the revert flag and pastBlockTime.
        // For the deciding call we assert: either it reverted, or it succeeded with a
        // positive recorded timestamp (the block.timestamp + 1 update).
        assert(reverted || afterTimestamp > 0);
    }

    receive() external payable {}
}

