contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint value, uint targetTime) public payable {
        require(address(this).balance >= value);
        require(targetTime >= block.timestamp);

        // Setup: set pastBlockTime to a known past value by calling fallback with 10 ether.
        // To avoid using c.fallback directly (which causes parser error in some solc versions),
        // we perform a low-level call on the address of c.
        (bool setupSuccess, ) = address(c).call{value: 10 ether}("");
        require(setupSuccess, "setup call failed");
        uint pastAfterSetup = c.pastBlockTime();

        // Now perform the deciding call with the given value and targetTime.
        // We cannot control block.timestamp, so if targetTime != current block.timestamp the
        // condition block.timestamp > pastBlockTime may be false. We make the call directly.
        (bool success, ) = address(c).call{value: value}("");

        // According to the contract, the call succeeds iff value == 10 ether and
        // block.timestamp > pastBlockTime. Since we cannot alter block.timestamp, we
        // determine the expected outcome based on the current block.timestamp.
        bool expectedRevert = !(value == 10 ether && block.timestamp > pastAfterSetup);

        if (expectedRevert) {
            assert(!success);
            assert(c.pastBlockTime() == pastAfterSetup);
        } else {
            assert(success);
            assert(c.pastBlockTime() == block.timestamp + 1);
        }
    }

    receive() external payable {}
}

