contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 amount, uint256 bump) public payable {
        require(address(this).balance >= amount);

        uint256 past0 = c.pastBlockTime();

        // drive the stored pastBlockTime to a known strictly larger value
        if (bump > 0) {
            require(address(this).balance >= 10 ether);
            c.fallback{value: 10 ether}();
        }

        uint256 pastBefore = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 pastAfter = c.pastBlockTime();
        uint256 balAfter = address(c).balance;

        // pastBefore should be strictly greater than the original value when we bumped
        if (bump > 0) {
            assert(pastBefore > past0);
        }

        // Core general rule: a fallback call reverts iff the value is not exactly 10 ether
        // (timestamp strictly increasing holds on the successful path; the prior setup
        // guarantees that for any executed successful-path timestamp pastBefore > past0,
        // and the call itself uses the current, hence strictly greater, timestamp).
        assert(reverted == (amount != 10 ether));

        // State effect on success: balance increases by exactly the sent value
        if (!reverted) {
            assert(balAfter == address(this).balance + amount - amount + amount);
            assert(pastAfter >= pastBefore + 1);
        } else {
            assert(pastAfter == pastBefore);
        }
    }
}

