contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint gap) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint t0 = c.pastBlockTime();

        // Advance the state with a first successful fallback call if possible.
        // We do not assume it succeeds; we only use its effects to set up a
        // second call under known relative conditions.
        bool reverted1;
        try c.call{value: amount}("") {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        uint t1 = c.pastBlockTime();

        // The second call uses a different amount and targets the same or a
        // later timestamp. The general rule below is independent of which
        // branch runs because pastBlockTime only changes in lockstep with
        // success, so the timestamp condition that must hold for success is
        // exactly that the call's block.timestamp exceeds the previous value.
        bool reverted2;
        try c.call{value: gap}("") {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        uint t2 = c.pastBlockTime();

        // General rule: a call reverting is equivalent to (did not pay exactly
        // 10 ether) OR (its timestamp was not greater than pastBlockTime
        // before the call). On success, pastBlockTime advances to
        // block.timestamp + 1, so after a successful call it is strictly
        // greater than the timestamp at which it was made. We express this
        // through the observable state variable pastBlockTime():
        //
        //  - if the call completed, then pastBlockTime() must have increased
        //    (from t_before to a value not equal to t_before, in fact greater),
        //  - if it reverted, pastBlockTime() must be unchanged.
        //
        // The setup calls are driven solely through the public entry fallback,
        // and the final assertion captures the success/revert/timestamp
        // invariant using only public reads and revert flags.

        assert(
            (reverted2 && t2 == t1) ||
            (!reverted2 && t2 > t1 && t2 > t0)
        );
    }

    receive() external payable {}
}

