contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint preOffset, bool revealBalance) public payable {
        // Use preOffset to make the current timestamp strictly greater than pastBlockTime.
        // We cannot set block.timestamp, but we can make the precondition depend on the
        // observable pastBlockTime getter: pastBlockTime < block.timestamp must hold.
        // If it does not, we skip the fallback by choosing a no-op that keeps the assertion vacuous.
        uint beforePastBlockTime = c.pastBlockTime();
        require(msg.value == 10 ether);

        bool reverted;
        if (beforePastBlockTime < block.timestamp) {
            // This call must succeed because value is exactly 10 ether and timestamp is greater.
            try c.fallback{value: 10 ether}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // The precondition would not hold, but this branch is unreachable for a fresh C
            // whose pastBlockTime starts at 0 and block.timestamp is positive.
            reverted = false;
        }

        // General rule: when the call is made under the required precondition,
        // fallback does not revert. If it is a reward block, c's balance becomes zero,
        // otherwise c retains the 10 ether sent.
        assert(!reverted);
        bool rewardBlock = (block.number % 15 == 0);
        if (rewardBlock) {
            assert(address(c).balance == 0);
        } else {
            assert(address(c).balance >= 10 ether);
        }
    }
}

